            int[] cur = queue.poll();
            for (int[] d : dirs) {
                int a = cur[0] + d[0], b = cur[1] + d[1];
                if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] == 1 && time[a][b] == -1) {
                    time[a][b] = time[cur[0]][cur[1]] + 1;
                    queue.add(new int[]{a, b});
                }
            }
        }
        List<List<Integer>> out = new ArrayList<>();
        for (int[] row : time) { List<Integer> r = new ArrayList<>(); for (int v : row) r.add(v); out.add(r); }
        return out;
    }
