class Solution {
    public int countNeverRot(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] g = new int[m][];
        for (int i = 0; i < m; i++) g[i] = grid[i].clone();
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (true) {
            List<int[]> toRot = new ArrayList<>();
            for (int i = 0; i < m; i++)
