def countNeverRot(grid):
    m, n = len(grid), len(grid[0])
    seen = [[False] * n for _ in range(m)]
    queue = deque()
    fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                seen[i][j] = True
                queue.append((i, j))
            elif grid[i][j] == 1:
                fresh += 1
    while queue:
        i, j = queue.popleft()
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < m and 0 <= b < n and grid[a][b] == 1 and not seen[a][b]:
                seen[a][b] = True
                fresh -= 1
                queue.append((a, b))
    return fresh

