func orangesRotting(grid [][]int) int {
    m, n := len(grid), len(grid[0])
    g := make([][]int, m)
    q := [][2]int{}
    fresh := 0
    for r := range grid {
        g[r] = append([]int(nil), grid[r]...)
        for c := 0; c < n; c++ {
            if g[r][c] == 2 {
                q = append(q, [2]int{r, c})
            } else if g[r][c] == 1 {
                fresh++
            }
        }
    }
    dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
    minutes := 0
    for len(q) > 0 && fresh > 0 {
        next := [][2]int{}
        for _, cell := range q {
            for _, d := range dirs {
                nr, nc := cell[0]+d[0], cell[1]+d[1]
                if nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] == 1 {
                    g[nr][nc] = 2
                    fresh--
                    next = append(next, [2]int{nr, nc})
                }
            }
        }
        q = next
        minutes++
    }
    if fresh > 0 {
        return -1
    }
    return minutes
}
